{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "The closest analogue sharing the N,N-diethylacetamide side chain and 2-aryl heteroaromatic core, [18F]-(R)-TRACK, showed high brain uptake after crossing the BBB in nonhuman primates, directly demonstrating meaningful CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Alpidem, a close imidazopyridine acetamide analogue, easily crossed the BBB in rat autoradiographic studies with a brain/plasma ratio of about 2.0-2.5 after systemic administration, supporting robust CNS exposure for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "STS-E412, a 5,7-dimethylpyrazolo[1,5-a]pyrimidine analogue sharing the query's core, was BBB-permeable in rats with a brain/plasma concentration ratio of 0.39, providing direct evidence that this heterocyclic core enters the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Zolpidem, a closely related imidazopyridine acetamide, achieved central exposure after oral dosing in rats with measurable CSF concentrations, confirming that this amide-linked heteroaryl class penetrates the CNS after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Compound 40, a pyrazolo[1,5-a]pyrimidine analogue, crossed the BBB in mice with brain exposure approximately three-fold higher than plasma, directly supporting meaningful CNS access for the query's core scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a pyrazolo[1,5-a]pyrimidine N,N-diethylacetamide (DPA-713-like TSPO ligand). Multiple close analogues with the same amide side chain or dimethylpyrazolopyrimidine core show direct in vivo BBB penetration across rats, mice, and nonhuman primates, with high brain uptake, measurable CSF/brain concentrations, and brain/plasma ratios consistent with meaningful CNS access. Physicochemical properties are also favorable. Therefore, the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or PET measurement for the exact query molecule was included in the supplied evidence, but multiple close analogues provide consistent direct in vivo CNS penetration data.",
    "Efflux transporter status was not directly measured for the query, but the consistent brain exposure of structurally similar analogues and favorable passive properties suggest adequate access.",
    "Species differences exist across the evidence set, but the multi-species agreement strengthens the conclusion."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

